-- =============================================================================
-- Custom DQ rules on clearance_usl (same table only, no alias, no window
-- functions). PK and FK rules are generated by COMPILE USL and are named after
-- their column; confirm with LIST DQ USL. These rules gate CLEAR decisions:
-- a CLEAR or CLEAR_WITH_STATEMENT may not be proposed while has_ingredients,
-- english_label or the market_code FK rule returns an invalid record for the GTIN.
-- =============================================================================

REGISTER DQ has_ingredients TABLE lightning.metastore.clearshelf.clearance_usl.product AS ingredients_text IS NOT NULL AND length(trim(ingredients_text)) > 0;
REGISTER DQ english_label TABLE lightning.metastore.clearshelf.clearance_usl.product AS lang = 'en' OR (ingredients_text_en IS NOT NULL AND length(trim(ingredients_text_en)) > 0);
REGISTER DQ known_relation TABLE lightning.metastore.clearshelf.clearance_usl.extracted_allergen AS relation IN ('contains','may_contain','free_from_claim','not_allergen');
